<?php
declare(strict_types=1);
require __DIR__ . '/../lib/bootstrap.php';
$user = require_admin();
$section = in_array($_GET['section'] ?? '', ['products','categories','gallery'], true) ? $_GET['section'] : 'products';

function posted_bool(string $key): int { return isset($_POST[$key]) ? 1 : 0; }
function delete_uploaded_path(string $relative): void {
    $full = realpath(PROJECT_ROOT . '/' . $relative);
    $root = realpath(UPLOAD_ROOT);
    if ($full && $root && str_starts_with($full, $root . DIRECTORY_SEPARATOR) && is_file($full)) {
        $variants = [$full];
        if (str_ends_with($full, '.webp')) {
            $variants[] = substr($full, 0, -5) . '-md.webp';
            $variants[] = substr($full, 0, -5) . '-sm.webp';
        }
        foreach ($variants as $variant) if (is_file($variant)) unlink($variant);
    }
}

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf();
    $action = (string)($_POST['action'] ?? '');
    try {
        if ($action === 'save_category') {
            $id = (int)($_POST['id'] ?? 0); $name = trim((string)$_POST['name']);
            if ($name === '') throw new RuntimeException('La categoría necesita un nombre.');
            $values = [$name, slugify($_POST['slug'] ?: $name), trim((string)$_POST['description']), (int)$_POST['sort_order'], posted_bool('active')];
            if ($id) { $values[]=$id; db()->prepare('UPDATE categories SET name=?,slug=?,description=?,sort_order=?,active=? WHERE id=?')->execute($values); }
            else db()->prepare('INSERT INTO categories(name,slug,description,sort_order,active) VALUES(?,?,?,?,?)')->execute($values);
            flash('success','Categoría guardada correctamente.'); redirect_admin('categories');
        }
        if ($action === 'archive_category') {
            db()->prepare('UPDATE categories SET active=0 WHERE id=?')->execute([(int)$_POST['id']]);
            flash('success','Categoría archivada. Los productos asociados se conservaron.'); redirect_admin('categories');
        }
        if ($action === 'save_product') {
            $id=(int)($_POST['id']??0); $name=trim((string)$_POST['name']); $sku=trim((string)$_POST['sku']);
            if($name==='') throw new RuntimeException('El producto necesita un nombre.');
            $price=$_POST['price']===''?null:(float)$_POST['price']; $compare=$_POST['compare_price']===''?null:(float)$_POST['compare_price'];
            $values=[(int)$_POST['category_id']?:null,$name,slugify($_POST['slug']?:$name),$sku?:null,trim((string)$_POST['brand'])?:null,trim((string)$_POST['short_description']),trim((string)$_POST['description']),$price,$compare,max(0,(int)$_POST['stock']),$_POST['stock_mode']==='track'?'track':'consult',posted_bool('featured'),posted_bool('on_offer'),posted_bool('active'),(int)$_POST['sort_order']];
            if($id){$values[]=$id;db()->prepare('UPDATE products SET category_id=?,name=?,slug=?,sku=?,brand=?,short_description=?,description=?,price=?,compare_price=?,stock=?,stock_mode=?,featured=?,on_offer=?,active=?,sort_order=? WHERE id=?')->execute($values);}else{db()->prepare('INSERT INTO products(category_id,name,slug,sku,brand,short_description,description,price,compare_price,stock,stock_mode,featured,on_offer,active,sort_order) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute($values);$id=(int)db()->lastInsertId();}
            if(!empty($_FILES['images']['name'][0])){
                foreach($_FILES['images']['name'] as $i=>$filename){$file=['name'=>$filename,'type'=>$_FILES['images']['type'][$i],'tmp_name'=>$_FILES['images']['tmp_name'][$i],'error'=>$_FILES['images']['error'][$i],'size'=>$_FILES['images']['size'][$i]];$uploaded=upload_file($file,'image');$stmt=db()->prepare('SELECT COUNT(*) FROM product_images WHERE product_id=?');$stmt->execute([$id]);$cover=(int)$stmt->fetchColumn()===0?1:0;db()->prepare('INSERT INTO product_images(product_id,path,alt_text,is_cover) VALUES(?,?,?,?)')->execute([$id,$uploaded['path'],$name,$cover]);}
            }
            flash('success','Producto guardado correctamente.'); header('Location: index.php?section=products&edit='.$id); exit;
        }
        if ($action === 'archive_product') { db()->prepare('UPDATE products SET active=0 WHERE id=?')->execute([(int)$_POST['id']]); flash('success','Producto despublicado.'); redirect_admin('products'); }
        if ($action === 'set_cover') { $id=(int)$_POST['image_id'];$stmt=db()->prepare('SELECT product_id FROM product_images WHERE id=?');$stmt->execute([$id]);$pid=(int)$stmt->fetchColumn();db()->beginTransaction();db()->prepare('UPDATE product_images SET is_cover=0 WHERE product_id=?')->execute([$pid]);db()->prepare('UPDATE product_images SET is_cover=1 WHERE id=?')->execute([$id]);db()->commit();flash('success','Portada actualizada.');header('Location: index.php?section=products&edit='.$pid);exit; }
        if ($action === 'update_image') { $id=(int)$_POST['image_id'];$stmt=db()->prepare('SELECT product_id FROM product_images WHERE id=?');$stmt->execute([$id]);$pid=(int)$stmt->fetchColumn();db()->prepare('UPDATE product_images SET alt_text=?,sort_order=?,focal_x=?,focal_y=? WHERE id=?')->execute([trim((string)$_POST['alt_text']),(int)$_POST['sort_order'],max(0,min(100,(int)$_POST['focal_x'])),max(0,min(100,(int)$_POST['focal_y'])),$id]);flash('success','Encuadre y datos de imagen actualizados.');header('Location: index.php?section=products&edit='.$pid);exit; }
        if ($action === 'delete_image') { $id=(int)$_POST['image_id'];$stmt=db()->prepare('SELECT * FROM product_images WHERE id=?');$stmt->execute([$id]);$img=$stmt->fetch();if($img){db()->prepare('DELETE FROM product_images WHERE id=?')->execute([$id]);delete_uploaded_path($img['path']);$next=db()->prepare('SELECT id FROM product_images WHERE product_id=? ORDER BY sort_order,id LIMIT 1');$next->execute([$img['product_id']]);if($nextId=$next->fetchColumn())db()->prepare('UPDATE product_images SET is_cover=1 WHERE id=?')->execute([$nextId]);}flash('success','Imagen eliminada.');header('Location: index.php?section=products&edit='.(int)($img['product_id']??0));exit; }
        if ($action === 'save_media') { $title=trim((string)$_POST['title']);if($title==='')throw new RuntimeException('El medio necesita un título.');$kind=$_POST['media_type']==='video'?'video':'image';$uploaded=upload_file($_FILES['media'],$kind);db()->prepare('INSERT INTO gallery_media(title,description,media_type,path,sort_order,active) VALUES(?,?,?,?,?,?)')->execute([$title,trim((string)$_POST['description']),$kind,$uploaded['path'],(int)$_POST['sort_order'],posted_bool('active')]);flash('success','Medio publicado en la galería.');redirect_admin('gallery'); }
        if ($action === 'update_media') { db()->prepare('UPDATE gallery_media SET title=?,description=?,sort_order=?,active=?,focal_x=?,focal_y=? WHERE id=?')->execute([trim((string)$_POST['title']),trim((string)$_POST['description']),(int)$_POST['sort_order'],posted_bool('active'),max(0,min(100,(int)$_POST['focal_x'])),max(0,min(100,(int)$_POST['focal_y'])),(int)$_POST['id']]);flash('success','Medio actualizado en línea.');redirect_admin('gallery'); }
        if ($action === 'delete_media') { $stmt=db()->prepare('SELECT path FROM gallery_media WHERE id=?');$stmt->execute([(int)$_POST['id']]);if($path=$stmt->fetchColumn()){db()->prepare('DELETE FROM gallery_media WHERE id=?')->execute([(int)$_POST['id']]);delete_uploaded_path($path);}flash('success','Medio eliminado.');redirect_admin('gallery'); }
    } catch (Throwable $e) { if(db()->inTransaction())db()->rollBack(); flash('error','No se pudo guardar: '.$e->getMessage()); redirect_admin($section); }
}

$categories=db()->query('SELECT * FROM categories ORDER BY sort_order,name')->fetchAll();
$products=db()->query('SELECT p.*,c.name category_name,(SELECT path FROM product_images i WHERE i.product_id=p.id ORDER BY i.is_cover DESC,i.sort_order,i.id LIMIT 1) cover FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.sort_order,p.id DESC')->fetchAll();
$gallery=db()->query('SELECT * FROM gallery_media ORDER BY sort_order,id DESC')->fetchAll();
$editing=null;$images=[];
if($section==='products'&&!empty($_GET['edit'])){$stmt=db()->prepare('SELECT * FROM products WHERE id=?');$stmt->execute([(int)$_GET['edit']]);$editing=$stmt->fetch();if($editing){$stmt=db()->prepare('SELECT * FROM product_images WHERE product_id=? ORDER BY is_cover DESC,sort_order,id');$stmt->execute([$editing['id']]);$images=$stmt->fetchAll();}}
$categoryEdit=null;if($section==='categories'&&!empty($_GET['edit'])){$stmt=db()->prepare('SELECT * FROM categories WHERE id=?');$stmt->execute([(int)$_GET['edit']]);$categoryEdit=$stmt->fetch();}
$flashes=take_flashes();$token=csrf_token();
echo '<link rel="stylesheet" href="admin-inline.css">';
?>
