<?php if($section==='products'): ?><header class="page-head"><div><p class="kicker">Catálogo</p><h1>Productos</h1></div><a class="primary button-link" href="?section=products&new=1">+ Nuevo producto</a></header>
<?php if(isset($_GET['new'])||$editing): $p=$editing?:['id'=>'','category_id'=>'','name'=>'','slug'=>'','sku'=>'','brand'=>'','short_description'=>'','description'=>'','price'=>'','compare_price'=>'','stock'=>0,'stock_mode'=>'consult','featured'=>0,'on_offer'=>0,'active'=>0,'sort_order'=>0];?><section class="panel"><h2><?=$editing?'Editar producto':'Nuevo producto'?></h2><form method="post" enctype="multipart/form-data" class="form-grid"><input type="hidden" name="csrf" value="<?=$token?>"><input type="hidden" name="action" value="save_product"><input type="hidden" name="id" value="<?=$p['id']?>"><label class="span-2">Nombre<input name="name" required value="<?=htmlspecialchars((string)$p['name'])?>"></label><label>Categoría<select name="category_id"><option value="">Sin categoría</option><?php foreach($categories as $cat):?><option value="<?=$cat['id']?>" <?=$p['category_id']==$cat['id']?'selected':''?>><?=htmlspecialchars($cat['name'])?></option><?php endforeach;?></select></label><label>SKU<input name="sku" value="<?=htmlspecialchars((string)$p['sku'])?>"></label><label>Slug<input name="slug" value="<?=htmlspecialchars((string)$p['slug'])?>"></label><label>Marca<input name="brand" value="<?=htmlspecialchars((string)$p['brand'])?>"></label><label>Precio<input name="price" type="number" min="0" step="1" value="<?=htmlspecialchars((string)$p['price'])?>"></label><label>Precio anterior<input name="compare_price" type="number" min="0" step="1" value="<?=htmlspecialchars((string)$p['compare_price'])?>"></label><label>Stock<input name="stock" type="number" min="0" value="<?=$p['stock']?>"></label><label>Control de stock<select name="stock_mode"><option value="consult" <?=$p['stock_mode']==='consult'?'selected':''?>>Consultar</option><option value="track" <?=$p['stock_mode']==='track'?'selected':''?>>Controlar unidades</option></select></label><label class="span-2">Descripción breve<input name="short_description" maxlength="350" value="<?=htmlspecialchars((string)$p['short_description'])?>"></label><label class="span-2">Descripción<textarea name="description" rows="5"><?=htmlspecialchars((string)$p['description'])?></textarea></label><label>Orden<input name="sort_order" type="number" value="<?=$p['sort_order']?>"></label><label>Fotografías<input name="images[]" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><div class="checks span-2"><label><input type="checkbox" name="active" <?=$p['active']?'checked':''?>> Publicado</label><label><input type="checkbox" name="featured" <?=$p['featured']?'checked':''?>> Destacado</label><label><input type="checkbox" name="on_offer" <?=$p['on_offer']?'checked':''?>> En oferta</label></div><div class="form-actions span-2"><button class="primary">Guardar producto</button><a href="?section=products">Cancelar</a></div></form>
