<?php else:?><section class="table-panel"><table><thead><tr><th>Producto</th><th>Categoría</th><th>Precio</th><th>Stock</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><div class="product-cell"><?php if($p['cover']):?><img src="../<?=htmlspecialchars($p['cover'])?>" alt=""><?php endif;?><span><b><?=htmlspecialchars($p['name'])?></b><small><?=htmlspecialchars((string)$p['sku'])?></small></span></div></td><td><?=htmlspecialchars((string)$p['category_name'])?></td><td><?=$p['price']!==null?'$'.number_format((float)$p['price'],0,',','.'):'Cotizar'?></td><td><?=$p['stock_mode']==='track'?$p['stock']:'Consulta'?></td><td><span class="status <?=$p['active']?'live':'draft'?>"><?=$p['active']?'Publicado':'Borrador'?></span></td><td><a href="?section=products&edit=<?=$p['id']?>">Editar</a></td></tr><?php endforeach;?></tbody></table><?php if(!$products):?><div class="empty-admin">Aún no hay productos. Crea el primero.</div><?php endif;?></section><?php endif;?>
