<?php else:?><header class="page-head"><div><p class="kicker">Contenido visual</p><h1>Fotos y videos</h1></div></header><div class="admin-columns"><section class="panel"><h2>Agregar medio</h2><p class="help">Las fotos se convierten automáticamente a WebP y generan versiones de 480, 960 y 1600 px.</p><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=$token?>"><input type="hidden" name="action" value="save_media"><label>Título<input name="title" required></label><label>Descripción<textarea name="description" rows="4"></textarea></label><label>Tipo<select name="media_type"><option value="image">Fotografía</option><option value="video">Video</option></select></label><label>Archivo<input type="file" name="media" accept="image/jpeg,image/png,image/webp,video/mp4,video/webm" required></label><label>Orden<input type="number" name="sort_order" value="0"></label><label class="check"><input type="checkbox" name="active" checked> Publicado</label><button class="primary">Guardar medio</button></form></section><section class="media-admin"><?php foreach($gallery as $media):?><article><?php if($media['media_type']==='image'):?><img src="../<?=htmlspecialchars($media['path'])?>" alt="" style="object-position:<?=$media['focal_x']?>% <?=$media['focal_y']?>%"><?php else:?><video src="../<?=htmlspecialchars($media['path'])?>" muted controls></video><?php endif;?><form method="post" class="inline-media-form"><input type="hidden" name="csrf" value="<?=$token?>"><input type="hidden" name="action" value="update_media"><input type="hidden" name="id" value="<?=$media['id']?>"><label>Título<input name="title" value="<?=htmlspecialchars($media['title'])?>" required></label><label>Descripción<textarea name="description" rows="2"><?=htmlspecialchars((string)$media['description'])?></textarea></label><div class="mini-grid"><label>Orden<input name="sort_order" type="number" value="<?=$media['sort_order']?>"></label><?php if($media['media_type']==='image'):?><label>Foco X<input name="focal_x" type="range" min="0" max="100" value="<?=$media['focal_x']?>"></label><label>Foco Y<input name="focal_y" type="range" min="0" max="100" value="<?=$media['focal_y']?>"></label><?php else:?><input type="hidden" name="focal_x" value="50"><input type="hidden" name="focal_y" value="50"><?php endif;?></div><label class="check"><input type="checkbox" name="active" <?=$media['active']?'checked':''?>> Publicado</label><button>Guardar cambios</button></form><form method="post" onsubmit="return confirm('¿Eliminar este archivo?')"><input type="hidden" name="csrf" value="<?=$token?>"><input type="hidden" name="action" value="delete_media"><input type="hidden" name="id" value="<?=$media['id']?>"><button class="danger">Eliminar</button></form></article><?php endforeach;?></section></div><?php endif;?></main></body></html>
